import json
import re
import pandas as pd
def task_func(json_str):
    """
    Load a JSON string into a dictionary, normalize the dictionary by doubling the numerical values,
    and then create a Pandas DataFrame from the dictionary.

    Args:
        json_str: A JSON string representing a flat dictionary.

    Returns:
        A pandas DataFrame created from the normalized dictionary, or an empty DataFrame if the input
        is empty or does not contain valid data structures.
    """
    # Handle empty or invalid JSON string
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    # If the parsed data is not a dictionary, return empty DataFrame
    if not isinstance(data, dict):
        return pd.DataFrame()

    # If the dictionary is empty, return empty DataFrame
    if not data:
        return pd.DataFrame()

    # Normalize the dictionary by doubling numerical values
    normalized = {}
    for key, value in data.items():
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            normalized[key] = value * 2
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)) and not isinstance(item, bool):
                    new_list.append(item * 2)
                elif isinstance(item, str):
                    # Try to extract numbers from string using regex
                    numbers = re.findall(r'-?\d+\.?\d*', item)
                    if numbers:
                        # If the string contains numbers, double them
                        # But we need to decide: do we convert the whole string to a number?
                        # The problem says "strings that can be interpreted as numbers"
                        # So if the string is purely a number (possibly with whitespace), convert it
                        try:
                            num_val = float(item.strip())
                            new_list.append(num_val * 2)
                        except ValueError:
                            # If it's not a pure number, leave as is
                            new_list.append(item)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized[key] = new_list
        elif isinstance(value, str):
            # Try to interpret the string as a number
            try:
                num_val = float(value.strip())
                normalized[key] = num_val * 2
            except ValueError:
                # If it's not a number, leave as is
                normalized[key] = value
        else:
            # For other types (bool, None, etc.), leave as is
            normalized[key] = value

    # Create DataFrame from the normalized dictionary
    try:
        df = pd.DataFrame(normalized)
    except Exception:
        return pd.DataFrame()

    # Ensure numerical values are stored as floats
    for col in df.columns:
        if df[col].dtype in ['int64', 'float64']:
            df[col] = df[col].astype(float)

    return df

